class dng_srational
	{

	public:

		int32 n;		// Numerator
		int32 d;		// Denominator

	public:

		dng_srational ()
			: n (0)
			, d (0)
			{
			}

		dng_srational (int32 nn, int32 dd)
			: n (nn)
			, d (dd)
			{
			}

		void Clear ()
			{
			n = 0;
			d = 0;
			}

		bool IsValid () const
			{
			return d != 0;
			}

		bool NotValid () const
			{
			return !IsValid ();
			}

		bool operator== (const dng_srational &r) const
			{
			return (n == r.n) &&
				   (d == r.d);
			}

		bool operator!= (const dng_srational &r) const
			{
			return !(*this == r);
			}

		real64 As_real64 () const;

		void Set_real64 (real64 x, int32 dd = 0);

		void ReduceByFactor (int32 factor);

	};

