import random
import struct
from typing import List

def _rand(seed: int) -> random.Random:
    r = random.Random()
    r.seed(seed)
    return r

# Helpers to build buffers of given size with content patterns that are valid when
# reinterpreted as float32/uint16/uint32 data. We keep total <= 2048 for each stub.

def _floats_to_bytes(vals: List[float]) -> bytes:
    return struct.pack('<' + 'f'*len(vals), *vals)

def _u16_to_bytes(vals: List[int]) -> bytes:
    return struct.pack('<' + 'H'*len(vals), *vals)

def _s16_to_bytes(vals: List[int]) -> bytes:
    return struct.pack('<' + 'h'*len(vals), *vals)

def _u32_to_bytes(vals: List[int]) -> bytes:
    return struct.pack('<' + 'I'*len(vals), *vals)

# Source for DoCopyAreaR32_*: provide float data primarily in [0,1] to map nicely to 8/16-bit ranges.

def _src_float_block(r: random.Random, count: int, extra_patterns: bool = True) -> bytes:
    vals: List[float] = []
