        if extra_patterns:
            # Mix in a gentle sinusoidal and some clamped noise
            base = 0.6*base + 0.4*(0.5 + 0.5*math_sin(2.0*3.14159265*t))
            base += (r.random() - 0.5) * 0.02
        # clamp to [0,1]
        if base < 0.0: base = 0.0
        if base > 1.0: base = 1.0
        vals.append(base)
    return _floats_to_bytes(vals)

# Patterns for RepeatArea* (uint8/16/32) and EqualArea*

def _pattern_bytes_u8(r: random.Random, rows: int, cols: int) -> bytes:
    # simple gradient + modulo pattern
    out = bytearray(rows*cols)
    for rrow in range(rows):
        for ccol in range(cols):
            v = (rrow*3 + ccol*5) & 0xFF
            out[rrow*cols + ccol] = v
    return bytes(out)

def _pattern_bytes_u16(r: random.Random, rows: int, cols: int) -> bytes:
    vals = []
    for rr in range(rows):
        for cc in range(cols):
            vals.append(((rr*11 + cc*17) & 0xFFFF))
    return _u16_to_bytes(vals)

def _pattern_bytes_u32(r: random.Random, rows: int, cols: int) -> bytes:
    vals = []
    for rr in range(rows):
        for cc in range(cols):
            vals.append(((rr*2654435761 + cc*2246822519) & 0xFFFFFFFF))
    return _u32_to_bytes(vals)

# Vignette stubs need an image buffer; content can be ramp to see effect

def _s16_image(r: random.Random, rows: int, cols: int) -> bytes:
    vals = []
    for rr in range(rows):
        for cc in range(cols):
            # center-bright pattern in signed range
            dx = (cc - (cols-1)/2) / max(1.0, (cols-1)/2)
            dy = (rr - (rows-1)/2) / max(1.0, (rows-1)/2)
            dist = (dx*dx + dy*dy) ** 0.5
            base = int((1.0 - min(1.0, dist)) * 20000)  # approx within int16
            vals.append(max(-32768, min(32767, base)))
    return _s16_to_bytes(vals)

def _r32_image(r: random.Random, rows: int, cols: int) -> bytes:
    vals = []
    for rr in range(rows):
        for cc in range(cols):
            vals.append(max(0.0, min(1.0, (rr+cc) / max(1.0, (rows+cols-2)))))
    return _floats_to_bytes(vals)

# MapArea16 needs a data block of uint16 values within [0,255] (map size) to be safe.

def _u16_clamped_block(r: random.Random, count: int, maxval: int) -> bytes:
    vals = [r.randrange(0, maxval+1) for _ in range(count)]
    return _u16_to_bytes(vals)

# math.sin without importing full math each call

def math_sin(x: float) -> float:
    import math
    return math.sin(x)

# Build a composite seed buffer that will be parceled out by FUZZ_PARAM_STR calls.
# We concatenate segments that target each stub category; the harness will slice as needed.

def generate(seed: int) -> bytes:
    r = _rand(seed)
    chunks: List[bytes] = []

    # 1) Float sources for CopyAreaR32_* with sizes up to ~1024 floats (4KB) but fuzzer caps 2048 total per call.
    # Here provide a few small-to-medium sequences commonly chosen by modulo in stubs.
    for count in (64, 128, 256):
        chunks.append(_src_float_block(r, count))

    # 2) Patterns for RepeatArea8/16/32 (patRows=1). Provide several widths for variety.
    for cols in (5, 9, 13, 17):
        chunks.append(_pattern_bytes_u8(r, 1, cols))
    for cols in (4, 7, 11):
        chunks.append(_pattern_bytes_u16(r, 1, cols))
    for cols in (3, 5, 7):
        chunks.append(_pattern_bytes_u32(r, 1, cols))

    # 3) EqualArea buffers: provide pairs of identical and slightly different data at various element sizes.
    # 8-bit equal
    eq8 = _pattern_bytes_u8(r, 1, 64)
    chunks.append(eq8)
    # 8-bit different
    diff8 = bytearray(eq8)
    if len(diff8) > 0:
        idx = r.randrange(0, len(diff8))
        diff8[idx] ^= 0xFF
    chunks.append(bytes(diff8))
    # 16-bit equal
    eq16 = _pattern_bytes_u16(r, 1, 32)
    chunks.append(eq16)
    # 16-bit different
    d16 = bytearray(eq16)
    if len(d16) >= 2:
        d16[0] ^= 0x01
    chunks.append(bytes(d16))
    # 32-bit equal/diff
    eq32 = _pattern_bytes_u32(r, 1, 16)
    chunks.append(eq32)
    d32 = bytearray(eq32)
    if len(d32) >= 4:
        d32[0] ^= 0xFF
    chunks.append(bytes(d32))

    # 4) Vignette images (int16 and float). Keep sizes small to fit under 2KB in harness.
    rows_cols = [(8, 8), (12, 10)]
    for (rows, cols) in rows_cols:
        chunks.append(_s16_image(r, rows, cols))
        chunks.append(_r32_image(r, rows, cols))

    # 5) MapArea16: buffer values constrained to 0..255; include an identity LUT as well.
    chunks.append(_u16_clamped_block(r, 64, 255))  # data
    # identity map 256 entries
    chunks.append(_u16_to_bytes([i for i in range(256)]))

    # 6) ShiftRight16: provide some 16-bit data
    chunks.append(_u16_to_bytes([(i*31) & 0xFFFF for i in range(64)]))

    # 7) BilinearRow16/32: provide source rows
    chunks.append(_u16_to_bytes([((i*7) & 0xFFFF) for i in range(64)]))
    chunks.append(_floats_to_bytes([i/63.0 for i in range(64)]))

    # Also include some random padding bytes to vary FUZZ_PARAM_STR sizes across calls
    chunks.append(os.urandom(r.randrange(16, 64)))

    data = b''.join(chunks)
    # Ensure overall size not too large (limit 4096 per requirement)
    return data[:4096]
